<template><view class="page"><view class="custom-nav" :style="{ paddingTop: statusBarHeight + 'px' }"><view class="nav-row"><text class="nav-icon" @click="goBack">←</text><text class="nav-title">Lorem Ipsum</text><text class="nav-icon" @click="generate">✅</text></view></view><view class="content"><view class="form-row"><text class="form-l">段落数</text><input class="form-input" v-model="paragraphs" type="number" /></view><view class="form-row"><text class="form-l">每段句数</text><input class="form-input" v-model="sentences" type="number" /></view><view class="li-btn" @click="generate"><text>生成</text></view><view class="li-result" v-if="output"><textarea class="li-text" :value="output" auto-height readonly /></view><view class="li-btn copy" v-if="output" @click="copyOutput"><text>复制</text></view></view></view></template><script setup>import { ref, onMounted } from "vue"
const statusBarHeight = uni.getSystemInfoSync().statusBarHeight || 20
const paragraphs = ref(3); const sentences = ref(5); const output = ref("")
var words = ["lorem","ipsum","dolor","sit","amet","consectetur","adipiscing","elit","sed","do","eiusmod","tempor","incididunt","ut","labore","et","dolore","magna","aliqua","enim","ad","minim","veniam","quis","nostrud","exercitation","ullamco","laboris","nisi","aliquip","ex","ea","commodo","consequat","duis","aute","irure","in","reprehenderit","voluptate","velit","esse","cillum","fugiat","nulla","pariatur","excepteur","sint","occaecat","cupidatat","non","proident","sunt","culpa","qui","officia","deserunt","mollit","anim","id","est"]
function generate() {
  var p = parseInt(paragraphs.value) || 3; var s = parseInt(sentences.value) || 5; var result = []
  for (var i = 0; i < p; i++) { var para = []; for (var j = 0; j < s; j++) { var wordCount = 8 + Math.floor(Math.random() * 8); var sent = []; for (var k = 0; k < wordCount; k++) sent.push(words[Math.floor(Math.random() * words.length)]); sent[0] = sent[0].charAt(0).toUpperCase() + sent[0].slice(1); para.push(sent.join(" ") + ".") } result.push(para.join(" ")) }
  output.value = result.join("\n\n")
}
function copyOutput() { uni.setClipboardData({ data: output.value, success: function() { uni.showToast({ title: "已复制", icon: "success" }) } }) }
function goBack() { uni.navigateBack() }
onMounted(function() { if (!uni.getStorageSync("isLoggedIn")) { uni.reLaunch({ url: "/pages/login/login" }); return } })
</script><style scoped>.page{min-height:100vh;background:#f5f7fb}.custom-nav{background:linear-gradient(135deg,#a29bfe,#6c5ce7);width:100%}.nav-row{height:88rpx;display:flex;align-items:center;padding:0 24rpx}.nav-icon{width:72rpx;text-align:center;font-size:48rpx;color:#fff;font-weight:700;flex-shrink:0}.nav-title{flex:1;text-align:center;font-size:32rpx;color:#fff;font-weight:600}.content{padding:24rpx}.form-row{display:flex;align-items:center;background:#fff;padding:20rpx 24rpx;border-radius:16rpx;margin-bottom:16rpx}.form-l{font-size:26rpx;color:#333;width:180rpx}.form-input{flex:1;font-size:28rpx;text-align:right}.li-btn{background:linear-gradient(135deg,#a29bfe,#6c5ce7);border-radius:16rpx;padding:24rpx;text-align:center;margin-bottom:24rpx}.li-btn text{font-size:30rpx;color:#fff;font-weight:600}.li-btn.copy{background:#636e72}.li-result{background:#fff;border-radius:20rpx;padding:24rpx;margin-bottom:24rpx}.li-text{width:100%;min-height:200rpx;font-size:26rpx;line-height:1.8;color:#333}</style>